import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"用户手册","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/index.md","filePath":"zh-CN/user-guide/index.md","lastUpdated":1788366161000}'),s={name:"zh-CN/user-guide/index.md"};function l(i,e,n,d,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="用户手册" tabindex="-1">用户手册 <a class="header-anchor" href="#用户手册" aria-label="Permalink to &quot;用户手册&quot;">​</a></h1><p>欢迎查阅 Lertaro 官方用户手册！Lertaro 是一款为 Windows 深度定制的极速文件检索与生产力启动器。通过在后台维护高效的内存索引树（NTFS / ReFS 基于底层 USN 变更日志，其他文件系统基于实时事件监听），实现千万级文件的毫秒级检索响应。</p><p>本手册系统化介绍了日常使用所需掌握的各项核心功能与高级特性：</p><ul><li><strong><a href="./getting-started.html">快速上手</a></strong> —— 安装与便携版使用、App 与 Service 架构职责、三种窗口形态（快速窗口 / 主窗口 / 内嵌窗口）及基础操作。</li><li><strong><a href="./search-syntax.html">搜索语法</a></strong> —— 智能模糊匹配、修饰符（<code>!</code> 排除、<code>&#39;</code> 精确、<code>^</code> 前缀、<code>$</code> 后缀、<code>|</code> 或条件）、盘符定向、路径模式与拼音别名匹配。</li><li><strong><a href="./hotkeys.html">热键与交互手势</a></strong> —— 全局热键速查表、搜索框 Logo 鼠标拖动与重置手势、鼠标快速导航级联菜单与核心固定按键。</li><li><strong><a href="./actions-and-preview.html">动作菜单与即时预览</a></strong> —— 结果上下文动作面板（<code>Ctrl+O</code>）、主窗口结果交互、内置 QuickLook 音视频/文档预览与插件富文本卡片。</li><li><strong><a href="./space-analyzer.html">空间分析</a></strong> —— 零磁盘 I/O 的极速 Treemap 矩形树状图与体积降序列表，轻松发现大文件。</li><li><strong><a href="./instant-answers.html">即时解答与关键词功能</a></strong> —— 始终生效的计算器、环境变量与运行命令，以及进程管理（<code>ps</code>）、窗口切换（<code>win</code>）、浏览器书签（<code>bb</code>）、浏览器历史（<code>bh</code>）、设置直达（<code>set</code>）等关键词插件。</li><li><strong><a href="./cli.html">命令行搜索（lff）</a></strong> —— 终端环境下的交互式模糊查找伴侣工具，共享内存索引，支持管道传参与 Shell 脚本联动。</li><li><strong><a href="./uri-protocol.html">URI 协议（lertaro://）</a></strong> —— 外部超链接、快捷方式与脚本直达搜索、设置分区及 LocalSend 传输。</li><li><strong><a href="./file-manager-support.html">支持的文件管理器</a></strong> —— Windows 原生文件对话框、Directory Opus、Total Commander、XYplorer、Files 等工具的内嵌与快速导航集成。</li><li><strong><a href="./settings/">设置项参考</a></strong> —— 运行状态、索引管理、通用选项、外观主题、热键绑定、插件配置等各项设置详细说明。</li><li><strong><a href="./troubleshooting.html">故障排查</a></strong> —— 全局热键失灵、索引未更新、输入法候选框及日志查看排查指南。</li><li><strong><a href="./donate.html">捐赠与支持</a></strong> —— 支持 Lertaro 的持续迭代与开源维护。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>如果你是初次接触 Lertaro，推荐从<a href="./getting-started.html"><strong>快速上手</strong></a>开始阅读。</p></div>',5)])])}const m=t(s,[["render",l]]);export{p as __pageData,m as default};
